/**
 * Worldnet Local Identity Engine
 * Rule-based, deterministic and free; nothing is generated by paid AI.
 * Inferred types and scenic colors are ALWAYS marked as inferred/decorative.
 * Official identity is only asserted when backed by source metadata.
 */
export const CATEGORY_WORDS = Object.freeze({
  'Loja': [/(?:^|[.\s/_-])(?:shop|shopping|store|market|marketplace|loja|vendas|compras|commerce|ecommerce|boutique)(?:$|[.\s/_-])/i, /loja virtual|com[eé]rcio eletr[oô]nico/i],
  'Blog': [/(?:^|[.\s/_-])(?:blog|blogger|diary|di[aá]rio)(?:$|[.\s/_-])/i],
  'Notícias': [/\b(?:not[ií]cias|jornal|news|newspaper|gazeta|press|magazine|reportagens)\b/i],
  'Wiki': [/(?:^|[.\s/_-])(?:wiki|encyclopedia|enciclop[eé]dia)(?:$|[.\s/_-])/i],
  'Comunidade': [/\b(?:forum|f[oó]rum|community|comunidade|rede social|social network|discuss[aã]o)\b/i],
  'Jogos': [/\b(?:games?|gaming|jogos?|videogames?|esports?|e-sports?|gameplay)\b/i],
  'Educação': [/\b(?:educa[cç][aã]o|universidade|university|college|school|escola|curso|learning|ensino)\b/i],
  'Tecnologia': [/\b(?:tecnologia|technology|developer|development|software|programa[cç][aã]o|coding|code|opensource|open.source|computing)\b/i],
  'Mídia': [/\b(?:v[ií]deo|video|stream|streaming|filmes?|cinema|tv|televis[aã]o|media|m[ií]dia)\b/i],
  'Música': [/\b(?:m[uú]sica|music|audio|radio|r[aá]dio|podcast|sound)\b/i],
  'Viagem': [/\b(?:travel|viagens?|turismo|hotel|voos?|flight|booking|reservas?)\b/i],
  'Finanças': [/\b(?:finan[cç]as|finance|bank|banco|investimentos?|payment|pagamentos?|pagamento)\b/i],
});
const order = Object.keys(CATEGORY_WORDS);
export function domainHash(value) {
  let n = 2166136261;
  for(const c of String(value || '')) n = Math.imul(n ^ c.charCodeAt(0), 16777619);
  return n >>> 0;
}
const hex = n => `#${n.toString(16).padStart(6,'0')}`;
export function rgbFromHsl(h, s, l) {
  h = ((h % 360) + 360) % 360;
  const f = n => {
    const k = (n + h / 30) % 12;
    const a = s * Math.min(l, 1 - l);
    return Math.round(255 * (l - a * Math.max(-1, Math.min(k - 3, 9 - k, 1))));
  };
  return (f(0) << 16) | (f(8) << 8) | f(4);
}
export function inferCategory(site = {}) {
  const declared = String(site.category || '').trim();
  if (declared && declared !== 'Site' && order.includes(declared)) {
    return { category: declared, confidence: site.categoryConfidence || 'estimativa', evidence: 'Categoria identificada; confiança preservada' };
  }
  // Important: a query about a subject is NOT proof that the linked domain belongs to that subject.
  // Use only the domain/official site title and actual descriptions, never queryTags/sourceTitle.
  const host=String(site.domain || '').toLowerCase();
  const domain = host.replace(/[._-]/g, ' ');
  const shortName=host.split('.')[0] || '';
  const domainPrefix={blog:'Blog',loja:'Loja',shop:'Loja',store:'Loja',wiki:'Wiki',forum:'Comunidade',news:'Notícias',game:'Jogos',music:'Música'};
  const prefixCategory=Object.entries(domainPrefix).find(([prefix])=>shortName.startsWith(prefix) && shortName.length>prefix.length+3)?.[1];
  const description = String(site.description || '').slice(0, 700);
  const title = site.official ? String(site.title || '').slice(0, 120) : '';
  const scored = [];
  for(const [category, patterns] of Object.entries(CATEGORY_WORDS)) {
    let score = 0;
    for(const re of patterns) {
      if(re.test(domain)) score += 4;
      if(re.test(description)) score += 3;
      if(title && re.test(title)) score += 2;
    }
    if(score) scored.push({category, score});
  }
  scored.sort((a,b)=>b.score-a.score || a.category.localeCompare(b.category));
  if (!scored.length || (scored[1] && scored[1].score===scored[0].score)) {
    if(prefixCategory)return {category:prefixCategory,confidence:'estimativa',evidence:'Prefixo do domínio'};
    return {category:'Site', confidence:'desconhecida', evidence:'Dados insuficientes'};
  }
  return {category:scored[0].category,confidence:'estimativa', evidence:'Identificada por palavras presentes no domínio ou descrição'};
}
const CATEGORY_HUES = Object.freeze({
  'Loja': 25, 'Blog': 288, 'Notícias': 204, 'Wiki': 162,
  'Comunidade': 324, 'Jogos': 271, 'Educação': 140,
  'Tecnologia': 188, 'Mídia': 344, 'Música': 48,
  'Viagem': 166, 'Finanças': 120, 'Site': null,
});
export function visualIdentity(site={}) {
  const detected=inferCategory(site);
  const seed=domainHash(site.id || site.domain || 'worldnet-central');
  const raw=String(site.color || '');
  const verified=Boolean(site.colorVerified && /^#[0-9a-f]{6}$/i.test(raw));
  // Distinct, procedural NEON color PER DOMAIN. Not a claimed real brand color.
  const categoryHue=CATEGORY_HUES[detected.category];
  const hue= categoryHue===null ? (seed%360) : (categoryHue + ((seed>>>7)%43)-21+360)%360;
  const saturation=.58+((seed>>>12)%24)/100;
  const accent=verified?Number.parseInt(raw.slice(1),16):rgbFromHsl(hue,saturation,.53);
  const secondary=rgbFromHsl(hue+40+((seed>>>15)%55),.72,.59);
  const tertiary=rgbFromHsl(hue+168,.63,.46);
  const glow=rgbFromHsl(hue,.84,.68);
  return { ...detected, accent, secondary, tertiary, glow,
    accentCss: hex(accent), secondaryCss: hex(secondary),
    colorSource: verified?'verificada':'decorativa', verified,
    seed,
    archetype: architectureType(detected.category, seed)
  };
}
export function architectureType(category, seed) {
  return ({'Loja':'market','Blog':'library','Notícias':'broadcast',
    'Wiki':'archive','Comunidade':'commons','Jogos':'arcade',
    'Educação':'campus','Tecnologia':'tech','Mídia':'studio',
    'Música':'concert','Viagem':'terminal','Finanças':'finance'})[category]
    || ['tower','kiosk','loft','pod','spire','stack','terrace','glass'][seed % 8];
}
export function billboardContent(site={}) {
  const id=visualIdentity(site);
  const title=site.displayName || (site.title && site.title!==site.domain?site.title:site.domain)||'SITE';
  // A public data description can be used; no synthetic slogans/advertisements.
  const description=String(site.description || '').trim();
  const subtitle=description ? description : id.category!=='Site' ? id.category.toUpperCase() : String(site.domain||'');
  return {title:String(title).slice(0,56),subtitle:subtitle.slice(0,110),descriptionAvailable:Boolean(description)};
}
